import openpyxl
from openpyxl import load_workbook

wb = load_workbook('/work/pi_rsitaram_umass_edu/tungi/ekb-claude-pilot/data/gaia/raw/5cfb274c-0207-4aa7-9575-6ac0bd95d9b2.xlsx')
ws = wb.active

# Find all green cells
green_cells = set()
for row in ws.iter_rows():
    for cell in row:
        fill = cell.fill
        if fill and fill.fgColor and fill.fgColor.type == 'rgb':
            color = fill.fgColor.rgb
            r = int(color[2:4], 16)
            g = int(color[4:6], 16)
            b = int(color[6:8], 16)
            if g > 100 and g > r * 1.5 and g > b * 1.5:
                green_cells.add((cell.row, cell.column))

print(f"Total green cells: {len(green_cells)}")
print("Cells:", sorted(green_cells))

# Build adjacency graph (4-directional)
def neighbors(r, c):
    return [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]

adj = {cell: [] for cell in green_cells}
for cell in green_cells:
    r, c = cell
    for n in neighbors(r, c):
        if n in green_cells:
            adj[cell].append(n)

print("\nAdjacency (degree of each cell):")
for cell in sorted(adj):
    print(f"  {cell}: degree={len(adj[cell])}, neighbors={adj[cell]}")

# Check if a Hamiltonian cycle exists using backtracking
cells = sorted(green_cells)
start = cells[0]
n = len(cells)

def hamiltonian_cycle():
    path = [start]
    visited = {start}

    def backtrack():
        if len(path) == n:
            # Check if we can return to start
            return start in adj[path[-1]]

        current = path[-1]
        for nxt in sorted(adj[current]):
            if nxt not in visited:
                path.append(nxt)
                visited.add(nxt)
                if backtrack():
                    return True
                path.pop()
                visited.remove(nxt)
        return False

    return backtrack()

result = hamiltonian_cycle()
print(f"\nHamiltonian cycle exists: {result}")
print(f"Answer: {'Yes' if result else 'No'}")

