import openpyxl
from collections import deque
wb = openpyxl.load_workbook('data/gaia/raw/65afbc8a-89ca-4ad5-8d62-355bb401f61d.xlsx')
ws = wb.active
BLUE = 'FF0099FF'
grid = {}
for r in range(1, ws.max_row+1):
    for c in range(1, ws.max_column+1):
        cell = ws.cell(r, c)
        try:
            rgb = cell.fill.fgColor.rgb
        except Exception as e:
            rgb = str(e)
        grid[(r,c)] = rgb
def is_blue(r,c):
    return grid.get((r,c), BLUE) == BLUE
dirs = {'D':(1,0), 'U':(-1,0), 'R':(0,1), 'L':(0,-1)}
opposite = {'D':'U', 'U':'D', 'R':'L', 'L':'R'}
q = deque()
q.append(((1,1), None, [(1,1)]))
paths = []
seen = set()
while q:
    pos, last_dir, path = q.popleft()
    if len(path) > 12:
        continue
    key = (pos, last_dir, len(path))
    if key in seen:
        continue
    seen.add(key)
    r, c = pos
    for dname, (dr, dc) in dirs.items():
        if last_dir and dname == opposite[last_dir]:
            continue
        nr, nc = r + 2*dr, c + 2*dc
        if 1 <= nr <= 20 and 1 <= nc <= 9 and not is_blue(nr, nc):
            new_path = path + [(nr, nc)]
            if len(new_path) == 12:
                paths.append(new_path)
            else:
                q.append(((nr, nc), dname, new_path))
print('Found', len(paths), 'valid 11-turn paths')
for p in paths[:3]:
    print(p)
